import { S3Client } from "@aws-sdk/client-s3";
import type { AppEnv } from "../config/env";

/**
 * Shared S3 client factory. The worker has an identical factory at
 * apps/worker/src/logs/s3-client.ts. Both MUST produce identical client
 * config, or presigned URLs generated by the API will fail signature
 * verification on MinIO/S3.
 *
 * When S3_ENDPOINT is set (MinIO local), use it with path-style addressing.
 * When unset (real AWS S3), use the default endpoint with virtual-host style.
 */
export function createS3Client(env: Pick<AppEnv,
  "S3_ENDPOINT" | "S3_REGION" | "S3_ACCESS_KEY_ID" | "S3_SECRET_ACCESS_KEY"
>): S3Client {
  const endpoint = env.S3_ENDPOINT || undefined;
  return new S3Client({
    region: env.S3_REGION,
    endpoint,
    forcePathStyle: !!endpoint,
    credentials: {
      accessKeyId: env.S3_ACCESS_KEY_ID,
      secretAccessKey: env.S3_SECRET_ACCESS_KEY,
    },
  });
}